<script lang="ts">import{InlineOverflow}from'./inline-overflow';import{TickRail}from'./tick-rail';import{Transform}from'./transform';import{AskAiButton}from'./ask-ai-button';import{ButtonGroup}from'./button-group';import{Button}from'./button';import{SplitButton}from'./split-button';import*as Dropdown from'$lib/components/ui/dropdown-menu/index.js';let{mode='tick',disabled=false}:{mode?:string;disabled?:boolean}=$props();let value=$state(5),show=$state(false),actions=$state(0);const items=[first,second,third]</script>
{#snippet first()}<button>First</button>{/snippet}{#snippet second()}<button>Second</button>{/snippet}{#snippet third()}<button>Third</button>{/snippet}
{#if mode==='overflow'}<InlineOverflow {items}/>{:else if mode==='tick'}<TickRail bind:value min={10} max={0} step={2}/><output>{value}</output>{:else if mode==='transform'}<Transform {show} keepMounted><button>Inside</button></Transform>{:else if mode==='ai'}<AskAiButton label="Ask" loading={disabled}/>{:else if mode==='group'}<ButtonGroup orientation="vertical"><Button>{#snippet children()}A{/snippet}</Button><Button>{#snippet children()}B{/snippet}</Button></ButtonGroup>{:else}<SplitButton label="Save" {disabled} onclick={()=>actions++}>{#snippet menu()}<Dropdown.Item>Draft</Dropdown.Item>{/snippet}</SplitButton><output>{actions}</output>{/if}
